"""FM-16P: original six-level pathways, no claims of empirical calibration."""
import sympy as s
from calibration_bank import LEVELS,L
M=s.Matrix
k,h,r,t,u,w=s.symbols('k h r t u w',real=True)
PATHS={'three-system':'MAT.systems.three','describe-transform':'MAT.transformation.describe','vector-components':'VEC.3d.components','justify-skew':'VEC.skew.justify'}
RATIONALES={
 'three-system':['Back-substitute in a triangular system.','Diagnose inconsistent coefficient dependence.','Solve a coupled three-variable system.','Construct equations from independent linear constraints.','Recover a missing constant from a fourth constraint.','Solve and classify a parameter-dependent system, including singular branches.'],
 'describe-transform':['Read standard basis images.','Distinguish reflection from rotation.','Describe a specific transformation geometrically.','Identify a composite transformation using geometric effects.','Recover a reflection from a fixed direction.','Classify an entire scaled-reflection family, including axis and scale; enrichment extension.'],
 'vector-components':['Translate unit-vector notation into components.','Distinguish position and displacement.','Recover point coordinates from a directed displacement.','Reconstruct a point from a section ratio.','Recover missing components using two independent constraints.','Classify component vectors from two prescribed distances and one prescribed component.'],
 'justify-skew':['Recognise proportional directions.','Explain why nonparallel alone is insufficient.','Use all three coordinates to prove skewness.','Convert endpoint descriptions and check intersection.','Recover parameter for intersection and prove all other cases skew.','Classify lines for two parameters and prove the exact intersection criterion.']}

def make(path,l,v):
 if path not in PATHS or l not in LEVELS or v not in (1,2,3):raise ValueError('Unknown cell')
 a=v+1;b=v+3;d=2*v+5
 if path=='three-system':
  P=M([a,-b,d]);A=M([[1,1,1],[1,2,0],[0,1,2]]);B=A*P
  if l==1:
   f=[M([a+1,-b,d+1])];q=f'Solve z={d+1}, y+z={d+1-b}, x+y={a+1-b} by back-substitution.';ans=L(f[0]);steps=[f'z={d+1}; then y={-b}.',f'The last equation gives x={a+1}.'];hint=['Start with the equation containing only z.','Substitute into the other two.'];mist='Treating the three equations as unrelated.'
  elif l==2:
   f=[False];q=f'A student says the system x+y+z={d}, 2x+2y+2z={2*d+1}, x-z={a} must have a unique solution because there are three equations. Explain.';ans='No solution.';steps=['The left side of the second equation is twice the first.',f'The right sides would need to satisfy {2*d+1}={2*d}, which is false. The third equation cannot remove this contradiction.'];hint=['Compare the first two equations.','Check their constants as well.'];mist='Counting equations instead of checking independence and consistency.'
  elif l==3:
   f=[P];q=f'Solve x+y+z={B[0]}, x+2y={B[1]}, y+2z={B[2]} by elimination and verify all three equations.';ans=L(P);steps=[f'From the second equation x={B[1]}-2y; from the third z=({B[2]}-y)/2.',f'Substituting into the first gives 3y={-3*b}, so y={-b}.',f'Back-substitution gives x={a}, z={d}.',f'The three left sides evaluate to {tuple(B)} as required.'];hint=['Express x and z in terms of y.','Use the first equation to find y.'];mist='Omitting a coordinate equation during verification.'
  elif l==4:
   P=M([d,a,b]);C=M([[1,1,1],[1,-1,0],[0,1,-2]]);Y=C*P;f=[P];q=f'Three signed quantities x,y,z total {Y[0]}. The first exceeds the second by {Y[1]}, and the second minus twice the third is {Y[2]}. Construct and solve the system, checking the original constraints.';ans=L(P);steps=[f'Translate to x+y+z={Y[0]}, x-y={Y[1]}, y-2z={Y[2]}.',f'Use x=y+{Y[1]} and y=2z+({Y[2]}).',f'The total then gives 5z={5*b}, so z={b}, y={a}, x={d}.',f'All three original constraints hold: {tuple(Y)}.'];hint=['Translate the verbal comparisons into equations.','Eliminate x and y to leave one equation.'];mist='Reversing the signed difference in the second constraint.'
  elif l==5:
   P=M([b,d,-a]);Y=A*P;f=[Y[2],P];q=f'Solve x+y+z={Y[0]}, x+2y={Y[1]}, y+2z=k subject to x-z={a+b}. Determine k and justify uniqueness.';ans=f'k={Y[2]}, (x,y,z)={L(P)}.';steps=[f'The fourth condition gives z=x-{a+b}.',f'The first two then give 2x+y={Y[0]+a+b} and x+2y={Y[1]}.',f'Elimination gives x={b}, y={d}, then z={-a}.',f'The remaining equation forces k={Y[2]}; the two equations in x,y have nonzero determinant 3.'];hint=['Use the extra condition before solving for k.','The remaining pair is nonsingular.'];mist='Treating k as an independent unknown after all three coordinates are fixed.'
  else:
   f=[M([d-(h-b)/(k-a)-b,b,(h-b)/(k-a)]),a,b,M([d-b-t,b,t])];q=f'For every real k,h solve x+y+z={d}, y={b}, x+y+({1}+k-{a})z={d}+h-{b}. Classify unique, infinitely many and no solutions; give every solution and justify completeness.';ans=f'k not equal to {a}: (x,y,z)={L(f[0])}; k={a}, h={b}: (x,y,z)={L(f[3])}, t real; otherwise no solution.';steps=[f'Subtract the first equation from the third to obtain (k-{a})z=h-{b}.',f'For k not equal to {a}, z=(h-{b})/(k-{a}); y={b} and x={d-b}-z, giving {L(f[0])}.',f'For k={a}, consistency requires h={b}. If it holds, choose z=t freely, yielding {L(f[3])}.',f'If k={a} and h differs from {b}, the reduced equation is a contradiction. These cases exhaust all parameters and substitution verifies each solution.'];hint=['Subtract equations before dividing by a parameter.','Separate zero and nonzero coefficient cases.'];mist='Dividing by k minus the singular value without checking it.'
 elif path=='describe-transform':
  if l==1:
   A=M([[0,-a],[a,0]]);f=[A[:,0],A[:,1]];q=f'Find the images of i=(1,0) and j=(0,1) under {L(A)}.';ans=f'{L(f[0])}, {L(f[1])}.';steps=[f'The first column is the image of i: {L(f[0])}.',f'The second column is the image of j: {L(f[1])}.'];hint=['Multiply by each basis vector.','Read the columns.'];mist='Reading rows as basis images.'
  elif l==2:
   A=M([[0,1],[1,0]]);P=M([a,b]);f=[A*P,A.det()];q=f'A student calls {L(A)} a 90 degree rotation. Test the point {L(P)} and explain the actual transformation.';ans='Reflection in y=x.';steps=[f'The map swaps coordinates: {L(P)} maps to {L(A*P)}.', 'All points (x,x) are fixed, and (1,-1) reverses direction; a quarter-turn does not fix a nonzero point. Thus this is reflection in y=x.'];hint=['Check a point on y=x.','Compare the action perpendicular to that line.'];mist='Assuming swapping coordinates is a quarter-turn.'
  elif l==3:
   A=M([[0,-1],[1,0]]) if v==1 else M([[-1,0],[0,-1]]) if v==2 else M([[0,1],[-1,0]]);angle=[90,180,270][v-1];f=[A[:,0],A[:,1],angle];q=f'Describe fully the transformation {L(A)}, giving its centre, angle and direction (anticlockwise convention).';ans=f'Rotation {angle} degrees anticlockwise about the origin.';steps=[f'The basis images are {L(f[0])} and {L(f[1])}.',f'They are the original unit axes turned {angle} degrees anticlockwise, retaining perpendicularity and unit lengths. The origin is fixed.'];hint=['Track the image of the positive x-axis.','Verify the image of the positive y-axis.'];mist='Confusing clockwise and anticlockwise rotation.'
  elif l==4:
   F=M([[1,0],[0,-1]]);Q=M([[0,-1],[1,0]]);A=a*Q*F;f=[A,A.det(),M([1,1])];q=f'A reflection in the x-axis is followed by an anticlockwise quarter-turn and then an enlargement of scale {a} about the origin. Find the composite matrix and describe it as an enlargement combined with a single reflection. Give the reflection axis.';ans=f'{L(A)}; scale {a} and reflection in y=x.';steps=['Reflection has matrix diag(1,-1); the quarter-turn has columns (0,1),(-1,0).',f'Multiply in the stated order and scale by {a} to give {L(A)}.',f'Dividing by {a} leaves the coordinate swap, fixing y=x and reversing its perpendicular direction.'];hint=['Rightmost matrix acts first.','Remove the positive scale and inspect the remaining map.'];mist='Reversing the transformation order, which changes the reflection axis.'
  elif l==5:
   D=M([1,a]);N=M([-a,1]);A=(D*D.T-N*N.T)/(1+a*a);f=[A,D,N];q=f'A reflection through a line through the origin fixes the point (1,{a}). Reconstruct its matrix, using a perpendicular direction that must reverse. Prove uniqueness.';ans=L(A);steps=[f'The fixed direction is {L(D)}; a perpendicular direction is {L(N)}.',f'The reflection fixes D and maps N to -N. Writing these as columns gives A[D,N]=[D,-N].',f'The two directions form an invertible basis, forcing A={L(A)}. This matrix satisfies both actions.'];hint=['Use a perpendicular direction.','Solve the matrix equation with both directions as columns.'];mist='Using only the fixed direction, which does not specify a general linear transformation.'
  else:
   A=M([[k-a,h],[h,a-k]]);rho=s.sqrt((k-a)**2+h*h);f=[rho,A.det(),M([rho+k-a,h]),M([h,rho-k+a])];q=f'For every real k,h describe the transformation {L(A)} as fully as possible. Determine when it is a pure reflection, when it is a positive enlargement followed by a reflection, and when it collapses the plane. Give an axis direction valid whenever the transformation is nonzero; prove your classification.';ans=f'Put p=k-{a}. (k,h)=({a},0): zero map; otherwise positive scale rho=sqrt(p^2+h^2) and reflection. Pure reflection iff rho=1. Axis direction (rho+p,h) unless zero, then (h,rho-p).';steps=[f'Put p=k-{a}. The columns are perpendicular and both have squared length p^2+h^2. At p=h=0 the entire plane maps to the origin.', 'Otherwise put rho=sqrt(p^2+h^2)>0. Dividing by rho gives a length-preserving matrix of determinant -1.', 'The normalized matrix fixes (rho+p,h) when this is nonzero; substitution uses rho^2=p^2+h^2. If it is zero, then h=0 and p=-rho, and (h,rho-p) is nonzero and fixed.', 'A perpendicular direction is negated (the normalized matrix is symmetric with determinant -1 and fixes a nonzero vector). Thus the normalized matrix is precisely reflection in the line spanned by the fixed direction.', 'The positive scale is rho, so the map is a pure reflection exactly on p^2+h^2=1, otherwise a non-unit enlargement combined with reflection. The zero and nonzero cases exhaust all parameters.'];hint=['Compare the columns and divide by their common length if nonzero.','Solve the fixed-direction equation after normalization, checking when your proposed vector vanishes.'];mist='Using a zero vector as an axis direction or confusing a scaled reflection with a pure reflection.'
 elif path=='vector-components':
  P=M([a,-b,d]);Q=M([b,a,-d]);D=Q-P
  if l==1:
   f=[P];q=f'Write {a}i - {b}j + {d}k in column-vector notation.';ans=L(P);steps=[f'The coefficients of i,j,k in order are {a}, {-b}, {d}. The column is {ans}.'];hint=['Read the coefficients including their signs.','Keep x,y,z order.'];mist='Dropping the minus sign on the j component.'
  elif l==2:
   f=[D];q=f'P={L(P)} and Q={L(Q)} are position vectors. A student says PQ has components P+Q. Explain and give the correct displacement.';ans=L(D);steps=['A displacement from P to Q is the change in position, final minus initial.',f'Q-P={ans}; adding the position vectors is not the displacement.'];hint=['Think of change in each coordinate.','Subtract the initial point.'];mist='Adding positions instead of subtracting.'
  elif l==3:
   W=M([d,b,-a]);R=P+W;f=[R];q=f'P has position {L(P)}. The displacement PQ is {d}i+{b}j-{a}k. Find Q in component notation and check the displacement.';ans=L(R);steps=[f'The given displacement is {L(W)}.',f'Q=P+PQ={ans}.',f'Check Q-P={L(W)}.'];hint=['Write the displacement as a column.','Add it to the initial position.'];mist='Subtracting the displacement from the initial position.'
  elif l==4:
   F=P+(Q-P)*s.Rational(a,a+1);f=[F];q=f'P={L(P)} and Q={L(Q)}. R divides PQ internally in ratio PR:RQ={a}:1. Find R as a column and in i,j,k notation. Verify the ratio.';ans=f'{L(F)} = ({L(F[0])})i+({L(F[1])})j+({L(F[2])})k.';steps=[f'PR is {L(s.Rational(a,a+1))} of PQ, so R=P+{L(s.Rational(a,a+1))}(Q-P).',f'Substitute the given positions to obtain {ans}.',f'The displacements PR and RQ are respectively {L(s.Rational(a,a+1))} and {L(s.Rational(1,a+1))} times PQ, proving the ratio.'];hint=['The total ratio has a+1 parts.','Use the directed displacement from P.'];mist='Reversing the weights of the two endpoints.'
  elif l==5:
   W=M([a,b,d]);f=[W,M([a,-b,d])];q=f'A vector has i-component {a}, k-component {d}, and squared magnitude {a*a+b*b+d*d}. Recover all possible j-components and write the vectors in component form. Explain why both are valid.';ans=f'{L(W)} and {L(f[1])}.';steps=[f'Write the vector as ({a},y,{d}).',f'The magnitude equation is {a*a}+y^2+{d*d}={a*a+b*b+d*d}, so y^2={b*b}.',f'Both y={b} and y={-b} satisfy the constraints.'];hint=['Use the squared magnitude to avoid radicals.','Take both square roots.'];mist='Assuming a component must be positive because length is positive.'
  else:
   X=(h*h-r*r)/(4*a);Y=r*r-(X-a)**2-b*b;f=[X,Y,M([X,s.sqrt(Y),b]),M([X,-s.sqrt(Y),b])];q=f'For all real prescribed distances r,h, find every point W with k-component {b}, distance r from P=({a},0,0) and distance h from Q=(-{a},0,0). Classify the number of solutions and prove completeness, including impossible distances.';ans=f'If either distance is negative, none. Otherwise x={L(X)}, y^2={L(Y)}, z={b}; zero, one or two solutions as the right side for y^2 is negative, zero or positive.';steps=['Distances cannot be negative, so exclude negative r or h first.',f'For W=(x,y,{b}), the squared equations are (x-{a})^2+y^2+{b*b}=r^2 and (x+{a})^2+y^2+{b*b}=h^2.',f'Subtract to obtain {4*a}x=h^2-r^2, hence x={L(X)}.',f'Substitute into the first equation: y^2={L(Y)}. Negative right side gives no points, zero gives one, positive gives two with opposite y components.', 'Each constructed point satisfies both squared equations. Since the prescribed distances are nonnegative, taking their nonnegative square roots recovers the original equations. The subtraction forces x, proving completeness.'];hint=['Subtract the squared distance equations.','Check the sign of the remaining squared component and the original distances.'];mist='Accepting negative prescribed distances after squaring.'
 else:
  U=M([1,a,0]);V=M([0,1,b]);P=M([d,0,1]);Q=P+V
  if l==1:
   f=[True,False];q=f'Which of (2,{2*a},0) and (1,{a},1) is parallel to (1,{a},0)? Explain.';ans='Only the first.';steps=['The first is twice the given vector.','The second has nonzero third component, impossible for any scalar multiple of the given vector.'];hint=['Check a common multiplier.','Zero components remain zero under scaling.'];mist='Checking only two coordinates.'
  elif l==2:
   f=[False];q=f'A student claims lines with directions (1,{a},0) and (0,1,{b}) must be skew because their directions are not parallel. Both lines pass through (0,0,0). Explain.';ans='They intersect at the origin and are not skew.';steps=['Nonparallel directions exclude parallelism only.','The common origin is an intersection, so the lines are not skew.'];hint=['Check whether they share a point.','Skew requires both nonparallel and disjoint.'];mist='Equating nonparallel with skew.'
  elif l==3:
   # L=(t,a*t,0), K=(d,u,1+b*u)
   T=d;U0=a*d;z0=1+b*U0;f=[T,U0,z0];q=f'Prove that L: (t,{a}t,0) and K: ({d},u,1+{b}u) are skew. Use all coordinate equations.';ans=f'Nonparallel; x,y force t={T}, u={U0}, but the third coordinate of K is {z0}, not zero.';steps=['The direction vectors have different zero components and are not proportional.',f'Equality of x and y forces t={T}, u={U0}.',f'Equality of z would require 0={z0}, which is false. Therefore no common point exists and the lines are skew.'];hint=['Solve x and y first.','Test the third coordinate independently.'];mist='Declaring an intersection from two matching coordinates.'
  elif l==4:
   P=M([1,2,3]);Q=P+U;R=M([2+d,2,4]);S=R+V;T=d+1;U0=a*(d+1);z0=1+b*U0;f=[U,V,T,U0,z0];q=f'Line L joins {L(P)} to {L(Q)}; K joins {L(R)} to {L(S)}. Derive both direction vectors and prove skewness by checking all coordinate equations.';ans=f'Directions {L(U)}, {L(V)}; forced parameters {T},{U0} leave a z discrepancy of {z0}.';steps=[f'Subtract endpoints to get directions {L(U)} and {L(V)}, which are nonparallel.',f'Write the lines as P+tU and R+uV. Matching x and y forces t={T}, u={U0}.',f'The z coordinate of K then exceeds that of L by {z0}; this is nonzero, so the lines are skew.'];hint=['Use end minus start for each direction.','Check all coordinates of any candidate common point.'];mist='Using position vectors themselves as directions.'
  elif l==5:
   K0=-b*a*d;F=M([d,a*d,0]);f=[K0,F];q=f'For real k consider L: (t,{a}t,0), K: ({d},u,k+{b}u). Determine k for which they intersect, find the intersection and prove they are skew for every other k.';ans=f'k={K0}, intersection {L(F)}; skew otherwise.';steps=['The directions are nonparallel for every k.',f'Matching x,y forces t={d}, u={a*d}.',f'The third coordinate agrees iff k+{b*a*d}=0, so k={K0}; the common point is {L(F)}. All other k give a contradiction.'];hint=['The unknown parameter appears only in the third coordinate.','Find the forced line parameters first.'];mist='Assuming the variable offset changes the direction.'
  else:
   T=d-h;U0=-h;F=M([T,0,0]);f=[T,U0,b-k*h,F];q=f'For all real k,h consider L: (t,0,0), K: ({d}+u,{b}+ku,h+u). Classify the pair as intersecting or skew, proving that no parallel or coincident case occurs. Give all intersection parameters and points whenever they exist.';ans=f'Intersect iff kh={b}, then t={d}-h, u=-h, point ({d}-h,0,0); otherwise skew.';steps=['Directions (1,0,0) and (1,k,1) are never proportional, because their third components differ in a way no scalar multiple can match.',f'Matching z forces u=-h and matching x then forces t={d}-h.',f'The remaining y equation is {b}-kh=0. If it holds the forced parameters give the common point {L(F)}; if it fails there is no intersection.',f'The conditions are both necessary and sufficient. The nonparallel directions exclude coincidence and parallelism, so every remaining pair is skew.'];hint=['Use the z equation, which has coefficient one.','Test the y constraint without dividing by k or h.'];mist='Dividing by a parameter and overlooking the zero case.'
 def enc(e):
  if type(e) is bool:return e
  if isinstance(e,s.MatrixBase):return {'matrix':[[str(x) for x in row] for row in e.tolist()]}
  return str(e)
 return dict(path=path,focus_skill=PATHS[path],tier=l,variant=v,assessment_role='prerequisite_bridge' if l==1 else 'concept_diagnostic' if l==2 else 'direct_focus_task',question_latex=q,final_answer_latex=ans,worked_solution_latex=steps,progressive_hints=hint,rubric=[dict(marks=1,criterion=e) for e in steps],facts=[enc(e) for e in f],likely_mistake=mist,origin='original',examination_source=None,difficulty_status='editorial_design_teacher_pending',demand_rationale=RATIONALES[path][l-1])
